#define OUI_FULL_COUNT (sizeof(ouiFullKeys) / sizeof(ouiFullKeys[0]))

inline const char *ouiLookupFull(uint32_t key)
{
    int lo = 0;
    int hi = (int)OUI_FULL_COUNT - 1;

    while (lo <= hi)
    {
        int mid = (lo + hi) / 2;

        if (ouiFullKeys[mid] == key)
            return ouiFullNames[mid];

        if (ouiFullKeys[mid] < key)
            lo = mid + 1;
        else
            hi = mid - 1;
    }

    return nullptr;
}
